// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract StructDemo {

    struct Student {
        string name;
        uint   age;
        string department;
    }

    // one Student stored on-chain
    Student public student;

    // set student data
    function setStudent(
        string memory _name,
        uint _age,
        string memory _department
    ) public {
        student = Student(_name, _age, _department);
    }

    // get student name only
    function getName() public view returns (string memory) {
        return student.name;
    }

}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract StudentList {

    struct Student {
        string name;
        uint   age;
    }

    // array of Student structs
    Student[] public students;

    // add a new student to the list
    function addStudent(
        string memory _name,
        uint _age
    ) public {
        students.push(Student(_name, _age));
    }

    // get total number of students
    function getCount() public view returns (uint) {
        return students.length;
    }

    // get one student by index
    function getStudent(uint _index)
        public view
        returns (string memory, uint)
    {
        Student memory s = students[_index];
        return (s.name, s.age);
    }

}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract MappingDemo {

    // address maps to a balance
    mapping(address => uint) public balances;

    // store balance for the caller
    function setBalance(uint _amount) public {
        balances[msg.sender] = _amount;
    }

    // read balance of any address
    function getBalance(address _addr)
        public view returns (uint)
    {
        return balances[_addr];
    }

    // add to caller's existing balance
    function addToBalance(uint _amount) public {
        balances[msg.sender] += _amount;
    }

}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract UserRegistry {

    struct User {
        string name;
        uint   age;
        bool   registered;
    }

    // each address maps to its own User struct
    mapping(address => User) public users;

    // register the calling wallet
    function register(
        string memory _name,
        uint _age
    ) public {
        require(!users[msg.sender].registered,
            'Already registered');
        users[msg.sender] = User(_name, _age, true);
    }

    // check if an address is registered
    function isRegistered(address _addr)
        public view returns (bool)
    {
        return users[_addr].registered;
    }

    // get name of any registered user
    function getName(address _addr)
        public view returns (string memory)
    {
        require(users[_addr].registered, 'Not registered');
        return users[_addr].name;
    }

}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract StudentManagement {

    struct Student {
        string name;
        uint   age;
        string department;
    }

    Student[] public students;

    mapping(address => bool) public hasRegistered;

    // add a student — one registration per wallet
    function addStudent(
        string memory _name,
        uint _age,
        string memory _department
    ) public {
        require(!hasRegistered[msg.sender],
            'You already registered a student');
        students.push(Student(_name, _age, _department));
        hasRegistered[msg.sender] = true;
    }

    // get total students
    function getTotalStudents()
        public view returns (uint)
    {
        return students.length;
    }

    // get one student by index
    function getStudent(uint _index)
        public view
        returns (string memory, uint, string memory)
    {
        require(_index < students.length, 'Index out of range');
        Student memory s = students[_index];
        return (s.name, s.age, s.department);
    }

}
